// GP (Gaussian process) regression on the 3D Road Network data: the
// altitude predicted from the position, for growing n.  The prediction is
// the function gp generated by ulm.lam (generated/gp.cpp, calling ulmBLAS);
// with -DWITH_MKL the same steps are also done by hand with MKL (Intel Math
// Kernel Library), as SciPy or scikit-learn linked against MKL would do:
// dpotrf, dpotrs, dgemv, dtrsm, dsyrk.
//
//   driver road.bin hyper.txt m n1 n2 ...   [out-prefix]
//
// road.bin: rows (x [km], y [km], altitude standardised), the first m rows
// are the test points, the following n the training points.  Prints per n
// the time of the kernel matrices and of the prediction, the RMSE (root
// mean square error) of the predicted altitude in metres, and the relative
// difference between ulm.lam and MKL.

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#include <vector>

#ifdef _OPENMP
#include <omp.h>
#endif
#ifdef WITH_MKL
#include <mkl.h>
#endif

extern "C" int64_t
gp(size_t n, size_t m, double *K, double *Ks, double *Kss, double *y,
   double *mean, double *cov, int8_t *work, int64_t *workspace_info);

namespace {

double
now()
{
    using namespace std::chrono;
    return duration<double>(steady_clock::now().time_since_epoch()).count();
}

struct Hyper
{
    double ell, var, noise;
};

// Matern 3/2: var (1 + sqrt(3) r / ell) exp(-sqrt(3) r / ell)
inline double
matern(const double *a, const double *b, const Hyper &h)
{
    double dx = a[0] - b[0], dy = a[1] - b[1];
    double s = std::sqrt(3.0 * (dx * dx + dy * dy)) / h.ell;
    return h.var * (1 + s) * std::exp(-s);
}

// K(i, j) = k(A_i, B_j), A and B rows of 3 doubles
void
kernel(const double *A, size_t na, const double *B, size_t nb, const Hyper &h,
       double *K)
{
#pragma omp parallel for schedule(static)
    for (size_t i = 0; i < na; ++i)
	for (size_t j = 0; j < nb; ++j)
	    K[i * nb + j] = matern(&A[3 * i], &B[3 * j], h);
}

double
relDiff(const double *a, const double *b, size_t len)
{
    double d = 0, r = 0;
    for (size_t i = 0; i < len; ++i) {
	d = std::max(d, std::fabs(a[i] - b[i]));
	r = std::max(r, std::fabs(b[i]));
    }
    return d / r;
}

} // namespace

int
main(int argc, char **argv)
{
    if (argc < 5) {
	std::fprintf(stderr, "usage: %s road.bin hyper.txt m n1 [n2 ...]\n",
	             argv[0]);
	return 2;
    }
    FILE *f = std::fopen(argv[1], "rb");
    if (!f) {
	std::perror(argv[1]);
	return 2;
    }
    std::fseek(f, 0, SEEK_END);
    size_t total = std::ftell(f) / (3 * sizeof(double));
    std::rewind(f);
    std::vector<double> P(3 * total);
    if (std::fread(P.data(), sizeof(double), P.size(), f) != P.size())
	return 2;
    std::fclose(f);
    Hyper h;
    FILE *hf = std::fopen(argv[2], "r");
    if (!hf || std::fscanf(hf, "%lf %lf %lf", &h.ell, &h.var, &h.noise) != 3)
	return 2;
    std::fclose(hf);
    size_t m = std::strtoul(argv[3], nullptr, 10);
    const double altStd = 18.6; // metres per standardised unit (prepare.py)

    int threads = 1;
#ifdef _OPENMP
    threads = omp_get_max_threads();
#endif
    std::printf("%zu points, m = %zu test points, Matern 3/2: length scale "
                "%.3f km, signal variance %.3f, noise variance %.5f, %d "
                "threads\n",
                total, m, h.ell, h.var, h.noise, threads);
    std::printf("%7s %9s %10s %9s %10s %9s %9s %10s %9s\n", "n", "kernel_s",
                "ulmlam_s", "GFLOP/s", "mkl_s", "rmse_m", "sd_m", "diff",
                "info");
    const double *Xt = P.data(), *Xn = P.data() + 3 * m;
    std::vector<double> Kss(m * m), mean(m), cov(m * m);
    kernel(Xt, m, Xt, m, h, Kss.data());

    for (int a = 4; a < argc; ++a) {
	size_t n = std::strtoul(argv[a], nullptr, 10);
	if (m + n > total) {
	    std::fprintf(stderr, "n = %zu: only %zu points\n", n, total - m);
	    return 2;
	}
	double t0 = now();
	std::vector<double> K(n * n), Ks(n * m), y(n);
	kernel(Xn, n, Xn, n, h, K.data());
	for (size_t i = 0; i < n; ++i) {
	    K[i * n + i] += h.noise;
	    y[i] = Xn[3 * i + 2];
	}
	kernel(Xn, n, Xt, m, h, Ks.data());
	double tKernel = now() - t0;

	// K is overwritten by both: the second one gets it anew.  The order
	// (GP_HAND_FIRST=1: MKL by hand first) shows whether the first run
	// pays for the placement of fresh memory.
	auto refill = [&] {
	    kernel(Xn, n, Xn, n, h, K.data());
	    for (size_t i = 0; i < n; ++i)
		K[i * n + i] += h.noise;
	};
	int64_t info = 0;
	double tLam = NAN, tMkl = NAN, diff = NAN;
	std::vector<double> mMean(m), mCov;
	auto runLam = [&] {
	    // ulm.lam: workspace query, then the call (K is overwritten)
	    int64_t ws = -1;
	    gp(n, m, K.data(), Ks.data(), Kss.data(), y.data(), mean.data(),
	       cov.data(), nullptr, &ws);
	    std::vector<int8_t> work(ws);
	    double t0 = now();
	    info = gp(n, m, K.data(), Ks.data(), Kss.data(), y.data(),
	              mean.data(), cov.data(), work.data(), &ws);
	    tLam = now() - t0;
	    work = {};
	};
	bool hasMkl = false;
#ifdef WITH_MKL
	hasMkl = true;
	auto runHand = [&] {
	    std::vector<double> alpha(y), V(Ks);
	    mCov = Kss;
	    bool prof = std::getenv("GP_PROF") != nullptr;
	    double t0 = now();
	    // K is symmetric: column-major upper is the same buffer as
	    // row-major lower (LAPACKE with LAPACK_ROW_MAJOR would transpose
	    // into a copy)
	    {
		double tp = now();
		LAPACKE_dpotrf(LAPACK_COL_MAJOR, 'U', n, K.data(), n);
		if (prof)
		    std::fprintf(stderr, "  hand %-20s %8.3f s\n",
		                 "LAPACKE_dpotrf", now() - tp);
	    }
	    {
		double tp = now();
		LAPACKE_dpotrs(LAPACK_COL_MAJOR, 'U', n, 1, K.data(), n,
		               alpha.data(), n);
		if (prof)
		    std::fprintf(stderr, "  hand %-20s %8.3f s\n",
		                 "LAPACKE_dpotrs", now() - tp);
	    }
	    {
		double tp = now();
		cblas_dgemv(CblasRowMajor, CblasTrans, n, m, 1.0, Ks.data(), m,
		            alpha.data(), 1, 0.0, mMean.data(), 1);
		if (prof)
		    std::fprintf(stderr, "  hand %-20s %8.3f s\n",
		                 "cblas_dgemv", now() - tp);
	    }
	    {
		double tp = now();
		cblas_dtrsm(CblasRowMajor, CblasLeft, CblasLower, CblasNoTrans,
		            CblasNonUnit, n, m, 1.0, K.data(), n, V.data(), m);
		if (prof)
		    std::fprintf(stderr, "  hand %-20s %8.3f s\n",
		                 "cblas_dtrsm", now() - tp);
	    }
	    {
		double tp = now();
		cblas_dsyrk(CblasRowMajor, CblasLower, CblasTrans, m, n, -1.0,
		            V.data(), m, 1.0, mCov.data(), m);
		if (prof)
		    std::fprintf(stderr, "  hand %-20s %8.3f s\n",
		                 "cblas_dsyrk", now() - tp);
	    }
	    {
		double tp = now();
		for (size_t i = 0; i < m; ++i)
		    for (size_t j = i + 1; j < m; ++j)
			mCov[i * m + j] = mCov[j * m + i];
		if (prof)
		    std::fprintf(stderr, "  hand %-20s %8.3f s\n", "mCov",
		                 now() - tp);
	    }

	    tMkl = now() - t0;
	};
#else
	auto runHand = [] {};
#endif
	if (hasMkl && std::getenv("GP_HAND_FIRST")) {
	    runHand();
	    refill();
	    runLam();
	} else {
	    runLam();
	    if (hasMkl) {
		refill();
		runHand();
	    }
	}
	if (hasMkl)
	    diff = std::max(relDiff(mean.data(), mMean.data(), m),
	                    relDiff(cov.data(), mCov.data(), m * m));

	double se = 0, sd = 0;
	for (size_t i = 0; i < m; ++i) {
	    double e = mean[i] - Xt[3 * i + 2];
	    se += e * e;
	    sd += std::sqrt(std::max(cov[i * m + i], 0.0) + h.noise);
	}
	double rmse = std::sqrt(se / m) * altStd, msd = sd / m * altStd;
	if (a + 1 == argc && std::getenv("GP_OUT")) {
	    FILE *o = std::fopen(std::getenv("GP_OUT"), "wb");
	    std::fwrite(mean.data(), sizeof(double), m, o);
	    std::fwrite(cov.data(), sizeof(double), m * m, o);
	    std::fclose(o);
	}

	// potrf, trsm, syrk (the O(n^2) and O(nm) parts are negligible)
	double nn = static_cast<double>(n), mm = static_cast<double>(m);
	double flops = nn * nn * nn / 3 + nn * nn * mm + nn * mm * mm;
	std::printf("%7zu %9.2f %10.2f %9.0f %10.2f %9.3f %9.3f %10.1e %9lld\n",
	            n, tKernel, tLam, flops / tLam * 1e-9, tMkl, rmse, msd,
	            diff, static_cast<long long>(info));
	std::fflush(stdout);
    }
    return 0;
}
